const q = $input.first().json.query || {};
const expected = "F1h0b14n4";
const ok = q["hub.mode"] === "subscribe" && q["hub.verify_token"] === expected;
return [{
  json: {
    ok,
    responseBody: ok ? String(q["hub.challenge"] || "") : "Forbidden",
  }
}];

// ============================================================================
// 1. Extraire sender + texte du payload webhook Meta. Ignore silencieusement
//    tout ce qui n'est pas un message texte (statuts de livraison, etc.).
// ============================================================================
const body = $input.first().json.body || {};
let sender = null, text = null;
for (const entry of (body.entry || [])) {
  for (const change of (entry.changes || [])) {
    for (const msg of ((change.value || {}).messages || [])) {
      if (msg.type === "text") { sender = msg.from; text = msg.text.body; }
    }
  }
}
if (!sender) return [];

// ============================================================================
// 2. Whitelist équipe Nuklear. Laisser vide = tout le monde autorisé.
// ============================================================================
// Vide par défaut = tout le monde autorisé (comme whatsapp.py::allowed_senders() côté Python).
// Remplir avec des numéros séparés par des virgules pour activer la whitelist équipe Nuklear.
const ALLOWED_SENDERS = ""; // ex: "+261340000000,+261320000000"
const allowedList = ALLOWED_SENDERS.split(",").map(s => s.trim()).filter(Boolean);
if (allowedList.length && !allowedList.includes(sender)) {
  return [{ json: { sender, needsBrain: false, text: "⛔ Accès réservé à l'équipe Nuklear.", image_url: null } }];
}

// ============================================================================
// 3. État de conversation persistant (mémoire n8n native -- survit entre
//    exécutions, pas de base de données requise).
// ============================================================================
const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};
const state = staticData.sessions[sender] || { stage: "idle", platform: null, current_idea: null, refine_notes: [] };

// ============================================================================
// 4. Parsing de commande.
// ============================================================================
const HELP_TEXT = [
  "🤖 *Nuklear Content Agent* — commandes disponibles:",
  "",
  "1️⃣ *gen image insta* / *gen image facebook*",
  "   → Idée de visuel basée sur les tendances + concurrents en temps réel. Idée libre : `gen image insta: astuce SEO local`",
  "",
  "2️⃣ *gen video*",
  "   → Prompt vidéo précis (avant/après, astuce, mythe vs réalité...).",
  "",
  "3️⃣ *actus* / *news*",
  "   → Actualités secteur + mouvements concurrents.",
  "",
  "Après une proposition :",
  "   ✅ *ok* / *valide* → génère le visuel final",
  "   🔄 *encore* / *autre* → relance une recherche d'idées",
  "   ✏️ *affine: <remarque>* → ajuste l'idée",
].join("\n");

function stripPunct(s) {
  const t = s.replace(/[\s!.?,;]+$/, "");
  return t || s;
}

function detectPlatform(low) {
  const aliases = [["insta", "instagram"], ["instagram", "instagram"], ["ig", "instagram"], ["fb", "facebook"], ["facebook", "facebook"]];
  for (const [alias, canon] of aliases) {
    if (new RegExp("\\b" + alias + "\\b").test(low)) return canon;
  }
  return null;
}

function splitFreeText(t) {
  const i = t.indexOf(":");
  if (i === -1) return [t.trim(), ""];
  return [t.slice(0, i).trim(), t.slice(i + 1).trim()];
}

const raw = text.trim();
const norm = stripPunct(raw.toLowerCase()) || raw.toLowerCase();

let cmd = "unknown", platform = null, freeText = "";

if (["help", "aide", "?", "menu"].includes(norm)) cmd = "help";
else if (["ok", "valide", "validé", "go", "oui", "✅"].includes(norm)) cmd = "validate";
else if (["encore", "autre", "autres", "relance", "🔄", "non"].includes(norm)) cmd = "refresh";
else {
  const refineMatch = raw.match(/^(affine|adapte|change)\s*[:\-]\s*([\s\S]+)$/i);
  if (refineMatch) {
    cmd = "refine"; freeText = refineMatch[2].trim();
  } else {
    const [head, free] = splitFreeText(raw);
    const lowHead = head.toLowerCase();
    if (/\b(actus?|news|actualit)/.test(lowHead)) cmd = "news";
    else if (/\b(g[eé]n(?:e|è)re?|gen|cr[eé]e?)\b.*\bvid/.test(lowHead)) { cmd = "gen_video"; freeText = free; }
    else if (/\b(g[eé]n(?:e|è)re?|gen|cr[eé]e?)\b.*\b(image|visuel|post)/.test(lowHead)) {
      cmd = "gen_image"; platform = detectPlatform(lowHead); freeText = free;
    }
  }
}

// ============================================================================
// 5. Commandes "rapides" (aucun appel externe nécessaire) traitées directement ici.
// ============================================================================
if (cmd === "help") return [{ json: { sender, needsBrain: false, text: HELP_TEXT, image_url: null } }];
if (cmd === "unknown") return [{ json: { sender, needsBrain: false, text: "Je ne comprends que des commandes précises. Tape *aide* pour voir la liste.", image_url: null } }];
if (cmd === "validate" && state.stage !== "idea_proposed") return [{ json: { sender, needsBrain: false, text: "Rien à valider. Lance d'abord *gen image insta*.", image_url: null } }];
if (cmd === "refresh" && state.stage !== "idea_proposed") return [{ json: { sender, needsBrain: false, text: "Aucune idée en cours. Lance d'abord *gen image insta* ou *gen image facebook*.", image_url: null } }];
if (cmd === "refine" && state.stage !== "idea_proposed") return [{ json: { sender, needsBrain: false, text: "Aucune idée à affiner. Lance d'abord une génération d'image.", image_url: null } }];

// ============================================================================
// 6. Limite quotidienne par expéditeur -- protège les forfaits gratuits partagés
//    par toute l'équipe (Tavily 1000 req/mois, Ollama Cloud, Cloudinary 25
//    crédits/mois). Sans ça, un usage un peu intensif épuise le quota du mois
//    en quelques jours sans que personne ne s'en rende compte à l'avance.
// ============================================================================
const DAILY_LIMIT_PER_SENDER = 15; // ~450/mois si utilisé tous les jours -- ajuster si besoin
const today = new Date().toISOString().slice(0, 10);
staticData.usage = staticData.usage || {};
const usageKey = `${sender}:${today}`;
staticData.usage[usageKey] = staticData.usage[usageKey] || 0;
if (staticData.usage[usageKey] >= DAILY_LIMIT_PER_SENDER) {
  return [{ json: {
    sender, needsBrain: false,
    text: `⏳ Limite quotidienne atteinte (${DAILY_LIMIT_PER_SENDER} générations/jour) pour préserver les forfaits gratuits partagés par l'équipe. Réessaie demain.`,
    image_url: null,
  } }];
}
staticData.usage[usageKey] += 1;

// ============================================================================
// 7. Tout le reste a besoin du cerveau (recherche + LLM + éventuellement image).
// ============================================================================
return [{ json: {
  sender, needsBrain: true, command: cmd,
  platform: platform || state.platform || "instagram",
  freeText, state,
} }];

// ============================================================================
// Config -- à remplacer avant activation.
// ============================================================================
const TAVILY_KEY = "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";
const OLLAMA_KEY = "fd57fa4c47304feb8b9fc67d0b08ed18.s-ok3iU3Ka3UTgle0Mx2Bqyg";
const OLLAMA_MODEL = "gpt-oss:20b-cloud";
const OLLAMA_FALLBACK_MODEL = "gemma3:4b-cloud";
const NUKLEAR_POSITIONING = "agence marketing / growth / SEO";
const BRAND_VOICE = "humoristique, sarcastique, décontracté mais expert — jamais corporate-plat";
const CLOUDINARY_CLOUD = "pme0bbhb";
const LOGO_PUBLIC_ID = "Logo_gtorte";
// Nom d'un "upload preset" Cloudinary en mode UNSIGNED (Settings > Upload > Upload presets).
// Sert au montage par UPLOAD (Cloudinary va chercher l'image lui-même, côté serveur), qui NE
// dépend PAS du réglage "Fetched URL" -- lequel est désactivé par défaut sur les comptes récents
// et bloque toute URL /image/fetch/ avec une 400 (cause racine du "montage indisponible").
// Laisser le placeholder si non configuré : le workflow bascule alors sur /image/fetch/ (si activé)
// puis, en dernier recours, sur l'image brute -- il fonctionne dans tous les cas.
const CLOUDINARY_UPLOAD_PRESET = "nuklear_unsigned";
// ⭐ CHEMIN LE PLUS FIABLE ET LE PLUS FIDÈLE À LA CHARTE. public_id d'un FOND DE MARQUE vierge
// (le gabarit sombre Nuklear SANS texte : fond noir, dégradé orange/teal, logo, forme géométrique)
// uploadé une fois dans la Media Library Cloudinary. Si renseigné, le visuel = CE gabarit + l'accroche
// incrustée par-dessus (aucune illustration IA générée). Comme c'est un asset STOCKÉ, sa livraison ne
// dépend NI du réglage "Fetched URL" NI d'un upload preset -> ça marche même quand tout le reste est
// bloqué. Laisser le placeholder = mode illustration IA (Pollinations) en repli.
const BRAND_TEMPLATE_PUBLIC_ID = "REPLACE_WITH_BRAND_TEMPLATE_PUBLIC_ID";
// Couleurs de marque Nuklear (utilisées pour la plaque de contraste et le badge de catégorie).
const BRAND_DARK = "040404";     // fond
const BRAND_ORANGE = "E23013";   // accent primaire
const BRAND_TEAL = "0E96A8";     // accent secondaire
const COMPETITOR_CACHE_TTL_MS = 24 * 60 * 60 * 1000; // 24h -- les concurrents ne changent pas d'un message à l'autre

const item = $input.first().json;
const { sender, command, platform, freeText, state } = item;

const staticData = $getWorkflowStaticData('global');
staticData.sessions = staticData.sessions || {};
staticData.competitorsCache = staticData.competitorsCache || {};

// ============================================================================
// Helpers réseau (this.helpers.httpRequest -- natif n8n Code node).
// Un seul retry après échec réseau transitoire : Tavily/Ollama Cloud peuvent
// avoir des blips passagers, un retry évite qu'un message WhatsApp entier
// échoue pour un simple timeout isolé.
// ============================================================================
async function httpRequestWithRetry(opts, retries) {
  try {
    return await this.helpers.httpRequest(opts);
  } catch (e) {
    if (retries > 0) {
      await new Promise(r => setTimeout(r, 500));
      return httpRequestWithRetry.call(this, opts, retries - 1);
    }
    throw e;
  }
}

async function tavilySearch(query, count) {
  try {
    const res = await httpRequestWithRetry.call(this, {
      method: "POST",
      url: "https://api.tavily.com/search",
      headers: { Authorization: `Bearer ${TAVILY_KEY}`, "Content-Type": "application/json" },
      body: { query, max_results: count },
      json: true,
      timeout: 15000,
    }, 1);
    return ((res && res.results) || []).map(r => ({ title: r.title, url: r.url, snippet: r.content }));
  } catch (e) { return []; }
}

function extractDomain(url) {
  if (!url || url.indexOf("://") === -1) return "";
  return url.split("://")[1].split("/")[0].replace(/^www\./, "");
}

// Plafond de collecte INTERNE (10), indépendant du maxResults de chaque appelant : synthesizeIdea
// demande 8, le handler "news" en demande 5 -- si on mettait en cache une liste tronquée à la
// taille du PREMIER appelant, un appel suivant qui en demande davantage serait silencieusement
// à court de résultats. On collecte toujours large, on tronque à la sortie selon l'appelant.
const COMPETITOR_COLLECT_CAP = 10;

async function discoverCompetitorsUncached(positioning) {
  const queries = [
    `agences concurrentes de ${positioning} Madagascar OR Afrique OR France`,
    `"${positioning}" alternative agency 2026`,
  ];
  let hits = [];
  for (const q of queries) hits = hits.concat(await tavilySearch.call(this, q, 10));
  const seen = new Set(); const profiles = [];
  for (const h of hits) {
    const domain = extractDomain(h.url);
    if (!domain || seen.has(domain) || domain.indexOf("nuklear") !== -1) continue;
    seen.add(domain);
    profiles.push({ name: h.title || domain, domain, snippet: h.snippet || "" });
    if (profiles.length >= COMPETITOR_COLLECT_CAP) break;
  }
  return profiles;
}

// Cache 24h : la découverte de concurrents coûte 2 requêtes Tavily -- sans cache, CHAQUE
// commande gen_image/gen_video/news relance cette découverte, épuisant vite le quota gratuit
// mensuel partagé par toute l'équipe (1000 req/mois Tavily).
async function discoverCompetitors(positioning, maxResults) {
  const cached = staticData.competitorsCache[positioning];
  if (cached && (Date.now() - cached.ts) < COMPETITOR_CACHE_TTL_MS) {
    return cached.data.slice(0, maxResults);
  }
  const data = await discoverCompetitorsUncached.call(this, positioning);
  staticData.competitorsCache[positioning] = { ts: Date.now(), data };
  return data.slice(0, maxResults);
}

async function ollamaComplete(model, system, user, jsonMode) {
  const payload = {
    model,
    messages: [{ role: "system", content: system }, { role: "user", content: user }],
    stream: false,
    options: { temperature: 0.85 },
  };
  if (jsonMode) payload.format = "json";
  const res = await httpRequestWithRetry.call(this, {
    method: "POST",
    url: "https://ollama.com/api/chat",
    headers: { Authorization: `Bearer ${OLLAMA_KEY}` },
    body: payload,
    json: true,
    timeout: 120000,
  }, 1);
  return res.message.content;
}

function extractJson(rawText) {
  const fenced = rawText.match(/```(?:json)?\s*(\{[\s\S]*?\})\s*```/);
  const candidate = fenced ? fenced[1] : rawText;
  try { return JSON.parse(candidate); } catch (e) {
    const brace = candidate.match(/\{[\s\S]*\}/);
    if (brace) return JSON.parse(brace[0]);
    throw e;
  }
}

async function completeJson(system, user) {
  try {
    const rawText = await ollamaComplete.call(this, OLLAMA_MODEL, system, user, true);
    return extractJson(rawText);
  } catch (e) {
    try {
      const rawText = await ollamaComplete.call(this, OLLAMA_FALLBACK_MODEL, system, user, true);
      return extractJson(rawText);
    } catch (e2) { return null; }
  }
}

function safeFloat(v, def) {
  const f = parseFloat(v);
  return Number.isFinite(f) ? f : def;
}

// ============================================================================
// Synthèse d'idée virale (LLM avec repli heuristique déterministe -- jamais
// d'échec silencieux : si Ollama tombe, une idée cohérente sort quand même).
// ============================================================================
async function synthesizeIdea(platformArg, hint, previousIdea) {
  const competitors = await discoverCompetitors.call(this, NUKLEAR_POSITIONING, 8);
  const trendHits = await tavilySearch.call(this, `contenu viral marketing agence ${platformArg} tendance 2026 humour`, 15);
  let competitorHits = [];
  for (const c of competitors.slice(0, 5)) {
    competitorHits = competitorHits.concat(await tavilySearch.call(this, `site:${c.domain} ${platformArg}`, 3));
  }

  let system = `Tu es directeur artistique ET copywriter de Nuklear (agence marketing/growth/SEO). Ton de marque : ${BRAND_VOICE}. Tu conçois UN visuel social VIRAL, digne d'un grand designer, prêt à publier. L'idée doit être CLAIRE, SIMPLE et INTÉRESSANTE : un angle fort compréhensible en 2 secondes, tiré des mécaniques les plus virales (astuce contre-intuitive, erreur #1 courante, secret/coulisses, chiffre choc, avant/après, mythe vs réalité, "personne ne te dit que..."). Réponds UNIQUEMENT en JSON avec EXACTEMENT ces clés :
- "hook" : l'accroche AFFICHÉE sur le visuel, EN FRANÇAIS PARFAIT (zéro faute), courte et percutante, ≤ 10 mots.
- "kicker" : 1 à 3 MOTS-CLÉS EN FRANÇAIS EN MAJUSCULES (le thème, ex: "SEO LOCAL", "ERREUR #1", "ASTUCE PRO"). Étiquette courte.
- "caption" : la LÉGENDE du post, EN FRANÇAIS, 1 à 3 phrases, ton Nuklear (simple, drôle, amical MAIS pro), qui développe l'idée et invite à agir/commenter. 1 emoji max, à la fin.
- "hashtags" : un tableau de 6 à 9 hashtags PERTINENTS et POPULAIRES (mélange large + niche marketing/SEO/réseaux sociaux), en minuscules, sans espace, chacun commençant par #.
- "visual_subject" : EN ANGLAIS, une SCÈNE riche, concrète et cinématographique qui illustre l'idée (peut inclure des PERSONNES RÉALISTES, un décor, une situation ; JAMAIS une icône plate). Ex: "a focused young entrepreneur working late at a glowing laptop in a cozy creative studio". AUCUN texte dans la description.
- "visual_style" : EN ANGLAIS, exactement l'un de : "cinematic photograph", "modern 3D render", "editorial digital illustration".
- "tone" : EN FRANÇAIS (ex: "humoristique", "inspirant", "expert").
- "confidence" : nombre 0 à 1.`;
  if (previousIdea) system += " Une idée a DÉJÀ été proposée, l'équipe demande un AJUSTEMENT -- garde le même angle sauf si la remarque dit le contraire.";

  const trends = trendHits.slice(0, 12).map(h => `- ${h.title}: ${h.snippet}`).join("\n");
  const comps = competitorHits.slice(0, 10).map(h => `- ${h.title}: ${h.snippet}`).join("\n");
  let previousBlock = "";
  if (previousIdea) previousBlock = `\nIdée précédemment proposée (à AJUSTER) :\n- Accroche: ${previousIdea.hook}\n- Concept: ${previousIdea.visual_concept}\n- Ton: ${previousIdea.tone}\n`;
  const user = `Plateforme cible : ${platformArg}\nConsigne équipe : ${hint || "(aucune)"}\n${previousBlock}\nTendances:\n${trends || "(rien)"}\n\nConcurrents:\n${comps || "(rien)"}\n\nPropose la meilleure idée.`;

  const sources = [...trendHits, ...competitorHits].map(h => h.url).filter(Boolean).slice(0, 5);
  const DEFAULT_TAGS = ["#marketingdigital", "#reseauxsociaux", "#growthhacking", "#seo", "#communitymanager", "#contentmarketing", "#nuklear"];
  const data = await completeJson.call(this, system, user);
  if (data) {
    return {
      hook: String(data.hook || hint || "Idée du jour"),
      kicker: String(data.kicker || data.tone || "NUKLEAR").toUpperCase().slice(0, 26),
      caption: String(data.caption || `${data.hook || "Une astuce qui change tout"} — on t'explique. 🚀`),
      hashtags: cleanHashtags(data.hashtags, DEFAULT_TAGS),
      visual_subject: String(data.visual_subject || data.illustration_subject || "a modern minimal marketing scene"),
      visual_style: String(data.visual_style || "editorial digital illustration"),
      visual_concept: String(data.visual_concept || data.visual_subject || ""),
      format: String(data.format || "post"),
      tone: String(data.tone || "humoristique"),
      inspired_by: sources,
      confidence: safeFloat(data.confidence, 0.8),
    };
  }
  if (previousIdea) {
    return {
      hook: previousIdea.hook,
      kicker: previousIdea.kicker || "NUKLEAR",
      caption: previousIdea.caption || `${previousIdea.hook} — on t'explique. 🚀`,
      hashtags: (previousIdea.hashtags && previousIdea.hashtags.length) ? previousIdea.hashtags : DEFAULT_TAGS,
      visual_subject: previousIdea.visual_subject || "a modern minimal marketing scene",
      visual_style: previousIdea.visual_style || "editorial digital illustration",
      visual_concept: hint ? `${previousIdea.visual_concept} — ajustement demandé: ${hint}` : previousIdea.visual_concept,
      format: previousIdea.format, tone: previousIdea.tone,
      inspired_by: sources.length ? sources : previousIdea.inspired_by, confidence: 0.65,
    };
  }
  const baseHook = hint || (trendHits[0] && trendHits[0].title) || "Astuce du jour";
  return {
    hook: baseHook,
    kicker: "NUKLEAR",
    caption: `${baseHook} — la méthode Nuklear pour passer à l'action. 🚀`,
    hashtags: DEFAULT_TAGS,
    visual_subject: "a modern minimal marketing workspace, cinematic lighting",
    visual_style: "editorial digital illustration",
    visual_concept: `Scène marketing, ton ${BRAND_VOICE}, format ${platformArg}, angle: ${baseHook}`,
    format: "post", tone: "humoristique", inspired_by: sources, confidence: hint ? 0.6 : 0.75,
  };
}

// Nettoie/normalise les hashtags renvoyés par le LLM : force le "#", retire espaces et caractères
// exotiques, dédoublonne, plafonne à 9. Repli sur un jeu par défaut si vide.
function cleanHashtags(arr, fallback) {
  if (!Array.isArray(arr)) return fallback;
  const seen = new Set(); const out = [];
  for (const raw of arr) {
    let h = String(raw).trim().replace(/^#+/, "").replace(/\s+/g, "").replace(/[^0-9A-Za-zÀ-ÿ_]/g, "");
    if (h.length < 2) continue;
    h = "#" + h.toLowerCase();
    if (!seen.has(h)) { seen.add(h); out.push(h); }
    if (out.length >= 9) break;
  }
  return out.length ? out : fallback;
}

function formatIdea(idea, platformArg) {
  const sources = idea.inspired_by.slice(0, 2).map(s => `• ${s}`).join("\n") || "• (analyse tendances en cours)";
  const tags = (idea.hashtags && idea.hashtags.length) ? idea.hashtags.slice(0, 6).join(" ") : "";
  return `💡 *Idée ${platformArg}* (confiance ${Math.round(idea.confidence * 100)}%)\n\n*Accroche:* ${idea.hook}\n*Légende:* ${idea.caption}\n${tags ? "*Hashtags:* " + tags + "\n" : ""}*Visuel:* ${idea.visual_style}, ${idea.visual_subject}\n\n_Inspiré de:_\n${sources}\n\n👉 *ok* pour générer · *encore* pour une autre · *affine: ...* pour ajuster.`;
}

// ============================================================================
// Génération d'image : Pollinations (base) -> Cloudinary /image/fetch/ (logo +
// texte "zéro faute garanti" + finition), tout en une URL. Aucune image
// n'est manipulée dans n8n -- seule une chaîne de caractères est construite.
// ============================================================================
function wrapCaption(text, maxCharsPerLine) {
  const words = text.split(/\s+/);
  const lines = []; let cur = words[0] || "";
  for (const w of words.slice(1)) {
    if ((cur + " " + w).length <= maxCharsPerLine) cur += " " + w; else { lines.push(cur); cur = w; }
  }
  lines.push(cur);
  return lines;
}

// Retire emojis + symboles que Cloudinary ne sait PAS graver dans un calque l_text: (ils
// ressortent en carrés/vides, voire cassent le rendu). Ils restent dans la légende WhatsApp
// (texte natif, toujours correct), juste pas incrustés dans l'image. Cas réel observé en prod :
// une accroche "... SANS ACCROCHE = 🍕" -- l'emoji n'a rien à faire gravé dans le visuel.
function stripForOverlay(s) {
  return String(s)
    .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2190}-\u{21FF}\u{2B00}-\u{2BFF}\u{FE00}-\u{FE0F}\u{200D}\u{20E3}]/gu, "")
    .replace(/\s{2,}/g, " ")
    .replace(/\s*[=:+\-]\s*$/, "") // enlève un séparateur resté seul après suppression d'un emoji final
    .trim();
}

// Encode le texte pour un paramètre l_text:. On encode une fois, puis on ré-encode UNIQUEMENT les
// séparateurs de transformation Cloudinary (virgule "," et slash "/") -> %252C / %252F, conformément
// à la doc officielle. (Ré-encoder toute la ligne rendrait espaces/accents illisibles si le CDN ne
// décode qu'une fois.) Une accroche vide après nettoyage tombe sur "Nuklear" pour ne jamais produire
// un l_text: vide (que Cloudinary rejette).
function encodeOverlayText(hook) {
  const cleaned = stripForOverlay(hook) || "Nuklear";
  const caption = cleaned.length > 220 ? cleaned.slice(0, 219) + "…" : cleaned;
  const lines = wrapCaption(caption, 28).slice(0, 4);
  return lines.map(l => encodeURIComponent(l).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F")).join("%0A");
}

// Chaîne de transformations commune au FETCH et à l'UPLOAD : plaque de fond + logo (optionnel) +
// texte (optionnel) + finition. Un public_id de logo rangé dans un dossier ("nuklear/logo") voit
// ses "/" remplacés par ":" (sinon le "/" casse le découpage de l'URL).
function overlayTransforms(withLogo, textLayer) {
  const width = 1080, height = 1350;
  const logoLayerId = LOGO_PUBLIC_ID.replace(/\//g, ":");
  const parts = [`c_pad,w_${width},h_${height},b_rgb:040404`];
  if (withLogo) parts.push(`l_${logoLayerId},g_south_east,x_40,y_40,w_190/fl_layer_apply`);
  if (textLayer) parts.push(`l_text:Arial_54_bold:${textLayer},co_white,c_fit,w_${width - 140},g_south,y_100,b_rgb:040404aa/fl_layer_apply`);
  parts.push(`e_sharpen:60`, `q_auto:best`);
  return parts.join("/");
}

function buildPollinationsUrl(prompt, negativePrompt) {
  const width = 1080, height = 1350;
  const fullPrompt = `${prompt} | avoid: ${negativePrompt}`;
  return `https://image.pollinations.ai/prompt/${encodeURIComponent(fullPrompt)}?width=${width}&height=${height}&nologo=true&model=flux`;
}

// Montage par FETCH : Cloudinary va chercher l'URL Pollinations via /image/fetch/. FRAGILE -- dépend
// du réglage compte "Fetched URL", DÉSACTIVÉ par défaut sur les comptes Cloudinary récents, ce qui
// fait échouer TOUTE URL /image/fetch/ avec une 400 (y compris sans overlay). Gardé comme repli au
// cas où le compte l'autorise, mais n'est plus le chemin principal.
function buildFetchTiers(pollinationsUrl, hook) {
  const t = encodeOverlayText(hook);
  const src = encodeURIComponent(pollinationsUrl);
  const root = `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/fetch`;
  return [
    { label: "fetch logo+texte", url: `${root}/${overlayTransforms(true, t)}/${src}` },
    { label: "fetch texte seul", url: `${root}/${overlayTransforms(false, t)}/${src}` },
    { label: "fetch logo seul", url: `${root}/${overlayTransforms(true, null)}/${src}` },
  ];
}

// Montage par UPLOAD : Cloudinary a déjà téléchargé et STOCKÉ l'image (via l'upload preset). Les
// transformations s'appliquent alors à un asset stocké normal (/image/upload/), ce qui NE dépend
// PAS du réglage "Fetched URL" -> fonctionne même quand /image/fetch/ est bloqué. C'est
// l'alternative sûre au point faible n°1 (dépendance à un réglage de sécurité caché).
function buildUploadTiers(publicId, hook) {
  const t = encodeOverlayText(hook);
  const root = `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/upload`;
  return [
    { label: "upload logo+texte", url: `${root}/${overlayTransforms(true, t)}/${publicId}` },
    { label: "upload texte seul", url: `${root}/${overlayTransforms(false, t)}/${publicId}` },
    { label: "upload logo seul", url: `${root}/${overlayTransforms(true, null)}/${publicId}` },
  ];
}

// Prompt pour une ILLUSTRATION de marque (fond du visuel riche) : style flat vector éditorial,
// palette Nuklear (noir + orange + teal), UN concept clair lié à l'idée, zone sombre réservée en bas
// pour le texte, aucun texte/personnage. Donne des illustrations différentes selon le contenu.
function buildIllustrationPrompt(idea) {
  // Visuel RICHE plein cadre (scène évocatrice, personnes réalistes possibles) et non plus une
  // petite icône plate sur fond vide. On garde le SUJET en anglais (flux ajoute du faux texte si on
  // lui donne l'accroche FR) + on impose un tiers inférieur SOMBRE pour y intégrer le titre sans
  // plaque. Négatifs stricts contre tout texte, mais PERSONNES autorisées (juste pas déformées).
  const subject = (idea.visual_subject && idea.visual_subject.trim()) || "a modern minimal marketing scene";
  const style = (idea.visual_style && idea.visual_style.trim()) || "editorial digital illustration";
  const p = `${style} of ${subject}. Professional editorial quality worthy of a top designer, rich detailed composition that FILLS the entire frame, dramatic moody lighting, subtle brand accents of orange (#E23013) and teal (#0E96A8), deep dark tones, a darker gradient across the lower third leaving clean space for a headline. Cohesive color grading, sharp, high quality, trending on Behance. No text, no words, no letters, no logo, no watermark.`;
  const neg = "text, words, letters, numbers, typography, captions, labels, ui, buttons, poster layout, mockup, watermark, signature, logo, frame, border, low quality, blurry, deformed, disfigured, extra limbs, extra fingers, mutated hands, ugly";
  return buildPollinationsUrl(p, neg);
}

// Montage RICHE, style ÉDITORIAL, sur une illustration uploadée (asset stocké). Le visuel plein cadre
// devient l'environnement ; le texte s'y intègre SANS plaque noire : on assombrit dégressivement le
// bas (dégradé sombre baké par Cloudinary) pour la lisibilité, on ajoute une OMBRE portée au titre,
// et une accroche colorée (kicker orange) crée la hiérarchie -- comme un vrai poster de designer.
// Transformation d'un asset stocké -> aucune dépendance à "Fetched URL".
function buildIllustrationCompositeTiers(publicId, idea) {
  const W = 1080, H = 1350, M = 72;
  const root = `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/upload`;
  const t = encodeOverlayText(idea.hook);
  const kicker = encodeURIComponent(String(idea.kicker || "NUKLEAR").toUpperCase()).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F");
  const logoLayerId = LOGO_PUBLIC_ID.replace(/\//g, ":");
  // Fond : plein cadre (recadrage intelligent) + assombrissement/contraste + VIGNETTE. La vignette
  // assombrit les coins/bords -> le LOGO (haut-gauche) et le TEXTE (bas) ressortent nettement, tandis
  // que la scène reste lumineuse au centre. C'est la solution "immersion + lisibilité" sans plaque.
  const fillFx = `c_fill,w_${W},h_${H},g_auto/e_brightness:-14/e_contrast:8/e_vignette:60`;
  const fillPlain = `c_fill,w_${W},h_${H},g_auto/e_brightness:-16`; // repli si un effet n'est pas dispo
  // Logo blanc (plus grand pour la visibilité).
  const logoLayer = `l_${logoLayerId},e_colorize:100,co_white,c_scale,w_220/fl_layer_apply,g_north_west,x_${M},y_${M}`;
  // Kicker : texte sombre sur ÉTIQUETTE BLANCHE (demandé) -> ressort fort, organise le visuel.
  const kickerLayer = `l_text:Arial_34_bold:${kicker},co_rgb:${BRAND_DARK},b_rgb:ffffff/fl_layer_apply,g_south_west,x_${M},y_360`;
  // Gros titre blanc, aligné à gauche, ombre portée pour rester lisible SANS plaque.
  const titleFx = `l_text:Arial_74_bold:${t},co_white,c_fit,w_${W - 2 * M},h_280,e_shadow:40/fl_layer_apply,g_south_west,x_${M},y_150`;
  const titlePlain = `l_text:Arial_74_bold:${t},co_white,c_fit,w_${W - 2 * M},h_280/fl_layer_apply,g_south_west,x_${M},y_150`;
  // Pied de marque orange en bas, SANS ombre (l'ombre rendait mal).
  const foot = `l_text:Arial_38_bold:nuklear.io,co_rgb:${BRAND_ORANGE}/fl_layer_apply,g_south_west,x_${M},y_74`;
  const finish = "q_auto:best";
  return [
    { label: "illustration éditoriale", url: `${root}/${[fillFx, logoLayer, kickerLayer, titleFx, foot, finish].join("/")}/${publicId}` },
    { label: "illustration + titre", url: `${root}/${[fillFx, logoLayer, titleFx, foot, finish].join("/")}/${publicId}` },
    { label: "illustration simple", url: `${root}/${[fillPlain, logoLayer, titlePlain, foot, finish].join("/")}/${publicId}` },
  ];
}

// Montage sur GABARIT DE MARQUE : le fond Nuklear vierge est un asset STOCKÉ ; on incruste juste
// l'accroche par-dessus. Livraison d'un asset stocké -> ne dépend NI de "Fetched URL" NI d'un upload
// preset. C'est le chemin le plus fiable ET le seul qui donne un rendu 100% fidèle à la charte
// (fond, dégradé, logo, forme déjà dans le gabarit). Renvoie [] si aucun gabarit n'est configuré.
function buildTemplateTiers(hook) {
  if (!BRAND_TEMPLATE_PUBLIC_ID || BRAND_TEMPLATE_PUBLIC_ID.indexOf("REPLACE_WITH") !== -1) return [];
  const t = encodeOverlayText(hook);
  const base = BRAND_TEMPLATE_PUBLIC_ID; // asset stocké : un "/" de dossier est OK en fin d'URL
  const root = `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/upload`;
  // L'accroche en gros, blanc, sur une plaque sombre pour rester lisible quelle que soit la zone du
  // gabarit. Placement par défaut au centre -- affinable précisément une fois le gabarit connu.
  const textLayer = `l_text:Arial_64_bold:${t},co_white,c_fit,w_880,g_center,y_0,b_rgb:${BRAND_DARK}cc`;
  return [
    { label: "gabarit marque + texte", url: `${root}/${textLayer}/fl_layer_apply/q_auto:best/${base}` },
    { label: "gabarit marque nu", url: `${root}/q_auto:best/${base}` }, // au pire : le fond de marque seul
  ];
}

// Encode une accroche pour un GROS titre (typo principale du gabarit) : lignes courtes, jusqu'à 5,
// adaptées à une grande taille de police.
function encodeHeadline(hook) {
  const cleaned = stripForOverlay(hook) || "Nuklear";
  const caption = cleaned.length > 160 ? cleaned.slice(0, 159) + "…" : cleaned;
  const lines = wrapCaption(caption, 16).slice(0, 5);
  return lines.map(l => encodeURIComponent(l).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F")).join("%0A");
}

// GABARIT DE MARQUE SYNTHÉTISÉ (auto-généré, AUCUN asset externe à fournir) : on part du LOGO
// (asset stocké), on le réduit et on le pose en haut à gauche sur un canevas sombre 1080x1350, puis
// on incruste un badge de catégorie (orange), le gros titre (accroche) et un pied de marque orange.
// Comme c'est la transformation d'un asset STOCKÉ, la livraison ne dépend NI de "Fetched URL" NI d'un
// upload preset -> c'est le chemin le plus fiable, et le rendu (fond sombre + typo + logo + accents
// orange) colle à la charte Nuklear, sans aucune illustration IA. Renvoie [] si le logo n'est pas
// configuré (on retombe alors sur l'illustration IA).
function buildBrandCanvasTiers(hook, badge) {
  if (!LOGO_PUBLIC_ID || LOGO_PUBLIC_ID.indexOf("REPLACE_WITH") !== -1) return [];
  const W = 1080, H = 1350;
  const root = `https://res.cloudinary.com/${CLOUDINARY_CLOUD}/image/upload`;
  const base = LOGO_PUBLIC_ID; // le logo sert de canevas de départ (asset stocké)
  const M = 72; // marge de sécurité commune
  const logoLayerId = LOGO_PUBLIC_ID.replace(/\//g, ":");
  // 1) CANEVAS : solide quasi-noir 1080x1350. On force les dimensions avec c_fill (fiable -- c_lpad
  //    depuis le logo laissait la taille native de l'asset, cassant la mise en page), puis on
  //    colorise TOUT en 040404 et on aplatit le fond -> canevas uniforme, indépendant du logo.
  const canvas = `c_fill,w_${W},h_${H},e_colorize:100,co_rgb:${BRAND_DARK},b_rgb:${BRAND_DARK}`;
  // NB : pas de "lueurs" ici -- un logo fin (wordmark sur transparent) flouté ne laisse quasiment
  // aucune matière, donc le halo est invisible sur fond noir. Le canevas auto reste donc un fond
  // sombre épuré (accents orange = badge + pied) ; la couleur/richesse vient du MODE ILLUSTRATION.
  // 2) LOGO blanc (calque, taille et position maîtrisées) en haut-gauche.
  const logoLayer = `l_${logoLayerId},e_colorize:100,co_white,c_scale,w_240/fl_layer_apply,g_north_west,x_${M},y_${M}`;
  // IMPORTANT : pour un CALQUE, la POSITION (g_/x_/y_) va AVEC fl_layer_apply, PAS dans l_text.
  // 3) gros titre blanc, aligné à gauche, centré verticalement.
  const title = `l_text:Arial_76_bold:${encodeHeadline(hook)},co_white,c_fit,w_${W - 2 * M},h_680/fl_layer_apply,g_west,x_${M}`;
  // 4) pied de marque orange en bas-gauche.
  const foot = `l_text:Arial_40_bold:nuklear.io,co_rgb:${BRAND_ORANGE}/fl_layer_apply,g_south_west,x_${M},y_84`;
  // 5) badge catégorie orange (fond plein) en haut-droite -- optionnel.
  const badgeClean = badge ? encodeURIComponent(badge).replace(/%2C/g, "%252C").replace(/%2F/g, "%252F") : "";
  const badgeLayer = badgeClean ? `l_text:Arial_30_bold:${badgeClean},co_white,b_rgb:${BRAND_ORANGE}/fl_layer_apply,g_north_east,x_56,y_84` : "";
  const finish = "q_auto:best";
  const full = [canvas, logoLayer, title, badgeLayer, foot, finish].filter(Boolean).join("/");
  const noBadge = [canvas, logoLayer, title, foot, finish].join("/");
  const minimal = [canvas, logoLayer, title, finish].join("/");
  return [
    { label: "gabarit auto + badge", url: `${root}/${full}/${base}` },
    { label: "gabarit auto", url: `${root}/${noBadge}/${base}` },
    { label: "gabarit auto minimal", url: `${root}/${minimal}/${base}` },
  ];
}

// Upload UNSIGNED depuis une URL distante : Cloudinary récupère l'image LUI-MÊME côté serveur
// pendant l'upload (indépendant du réglage fetch de livraison). Renvoie le public_id, ou null.
async function cloudinaryUploadFromUrl(sourceUrl) {
  // IMPORTANT : l'API d'upload Cloudinary attend du FORM-urlencoded, PAS du JSON. Envoyer du JSON
  // (json:true) fait échouer l'upload ("Missing required parameter - file"). On envoie donc un corps
  // application/x-www-form-urlencoded et on parse la réponse JSON à la main.
  const body = `file=${encodeURIComponent(sourceUrl)}&upload_preset=${encodeURIComponent(CLOUDINARY_UPLOAD_PRESET)}`;
  const res = await this.helpers.httpRequest({
    method: "POST",
    url: `https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD}/image/upload`,
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body,
    json: false,
    timeout: 90000,
  });
  let data = res;
  if (typeof res === "string") { try { data = JSON.parse(res); } catch (e) { data = {}; } }
  return (data && data.public_id) ? data.public_id : null;
}

// Extrait la vraie cause d'un échec httpRequest : Cloudinary la met dans l'en-tête x-cld-error,
// n8n dans e.message ("400 - ...") ou e.response. On la remonte jusqu'au message WhatsApp pour ne
// plus jamais diagnostiquer à l'aveugle.
function extractHttpError(e) {
  const resp = e && e.response;
  const hdr = (resp && (resp.headers || {})) || {};
  const cld = hdr["x-cld-error"] || hdr["X-Cld-Error"];
  if (cld) return String(cld).slice(0, 200);
  if (e && e.message) return String(e.message).slice(0, 200);
  return String(e).slice(0, 200);
}

// ============================================================================
// Routage par commande.
// ============================================================================
let result = { sender, text: "Commande non reconnue. Tape *aide*.", image_url: null };

if (command === "news") {
  const sectorHits = await tavilySearch.call(this, `actualités ${NUKLEAR_POSITIONING} 2026`, 8);
  const competitors = await discoverCompetitors.call(this, NUKLEAR_POSITIONING, 5);
  let lines = ["📰 *Veille Nuklear*\n"];
  for (const h of sectorHits) lines.push(`📈 secteur — ${h.title}\n${h.url}`);
  for (const c of competitors.slice(0, 5)) {
    const hits = await tavilySearch.call(this, `${c.name} actualité annonce 2026`, 2);
    for (const h of hits) lines.push(`🏢 concurrent — ${h.title}\n${h.url}`);
  }
  result.text = lines.length > 1 ? lines.join("\n\n") : "Aucune actualité pertinente trouvée pour le moment.";
}

else if (command === "gen_video") {
  const idea = await synthesizeIdea.call(this, "reels", freeText, null);
  const concept = "astuce_rapide";
  const beats = [
    `0-2s: accroche directe sur ${idea.hook}, cadrage serré`,
    "2-6s: démonstration de l'astuce en 2-3 étapes visuelles claires",
    "6-8s: résultat + punchline, logo Nuklear en overlay léger",
  ];
  let genPrompt = `Format: vidéo courte verticale 9:16, 8s max, style ${idea.tone}.\nConcept: ${concept}.\nAccroche: ${idea.hook}\nDécoupage:\n${beats.map(b => "- " + b).join("\n")}\nContraintes: texte ajouté en post-prod (police Inter) ; logo Nuklear en incrustation légère dernière seconde ; rythme dynamique.`;
  try {
    const refined = await ollamaComplete.call(this, OLLAMA_MODEL,
      `Tu es directeur créatif vidéo short-form pour Nuklear. Réécris UN prompt de génération vidéo précis à partir du concept/découpage fournis, style ${idea.tone}, français parfait. Réponds uniquement par le prompt.`,
      `Concept: ${concept}\nAccroche: ${idea.hook}\nDécoupage:\n${beats.map(b => "- " + b).join("\n")}`, false);
    if (refined && refined.trim()) genPrompt = refined.trim();
  } catch (e) { /* on garde le prompt template */ }
  result.text = `🎬 *Prompt vidéo virale* (concept: ${concept})\n\nAccroche: ${idea.hook}\n\nDécoupage:\n${beats.map(b => "  " + b).join("\n")}\n\n*Prompt de génération:*\n${genPrompt}`;
}

else if (command === "gen_image" || command === "refresh" || command === "refine") {
  // "refine" AJUSTE l'idée déjà proposée (previousIdea transmis) ; "refresh" en propose une
  // TOTALEMENT NOUVELLE (previousIdea = null) -- ne pas confondre les deux, comme côté Python
  // (orchestrator.py::_handle_refresh vs _handle_refine, testé explicitement).
  const previousIdea = (command === "refine") ? state.current_idea : null;
  const hint = (command === "refine" || command === "gen_image") ? freeText : null;
  const idea = await synthesizeIdea.call(this, platform, hint, previousIdea);
  staticData.sessions[sender] = { stage: "idea_proposed", platform, current_idea: idea, refine_notes: state.refine_notes || [] };
  const prefix = command === "refresh" ? "🔄 Nouvelle proposition:\n\n" : (command === "refine" ? "✏️ Idée adaptée:\n\n" : "");
  result.text = prefix + formatIdea(idea, platform);
}

else if (command === "validate") {
  const idea = state.current_idea;
  if (!idea) {
    // Garde-fou défensif : état incohérent (ne devrait pas arriver, Extract & Route l'exige) --
    // on ne crashe jamais l'exécution (ce qui laisserait WhatsApp sans réponse).
    staticData.sessions[sender] = { stage: "idle", platform: null, current_idea: null, refine_notes: [] };
    result.text = "Rien à valider. Lance d'abord *gen image insta*.";
    return [{ json: result }];
  }
  let chosen = null, lastError = "", uploadDiag = "";

  // Badge de catégorie (haut-droite) : 1er mot du ton, en capitales, ≤14 car., sans emoji -- cosmétique.
  const badge = String(idea.tone || "").split(/[\s,;/]+/)[0].toUpperCase().replace(/[^A-Z0-9ÉÈÀ]/g, "").slice(0, 14);
  const presetConfigured = CLOUDINARY_UPLOAD_PRESET && CLOUDINARY_UPLOAD_PRESET.indexOf("REPLACE_WITH") === -1;
  const illoUrl = buildIllustrationPrompt(idea); // illustration de marque Pollinations (déterministe)
  let illoWarm = false;

  // Essaie une liste de crans (arrow -> `this` = contexte n8n) ; renvoie le 1er qui répond 2xx.
  const tryTiers = async (tiers) => {
    for (const tier of tiers) {
      try {
        await this.helpers.httpRequest({ method: "GET", url: tier.url, timeout: 30000, json: false });
        return tier;
      } catch (e) { lastError = `${tier.label} → ${extractHttpError(e)}`; }
    }
    return null;
  };

  // ÉTAPE 0 -- GABARIT VIERGE fourni par l'utilisateur (fidélité charte maximale), si configuré.
  chosen = await tryTiers(buildTemplateTiers(idea.hook));

  // ÉTAPE 1 -- ILLUSTRATION IA DE MARQUE (visuel riche, différent selon le contenu). Activée UNIQUEMENT
  // si un upload preset est configuré : Pollinations génère une illustration flat-vector de marque,
  // Cloudinary la télécharge (upload, indépendant de "Fetched URL"), puis on compose titre + logo +
  // badge par-dessus. C'est ce que l'utilisateur demande (des illustrations qui portent l'idée).
  if (!chosen && presetConfigured) {
    try {
      await this.helpers.httpRequest({ method: "GET", url: illoUrl, timeout: 75000, json: false });
      illoWarm = true;
      const publicId = await cloudinaryUploadFromUrl.call(this, illoUrl);
      if (publicId) { uploadDiag = "ok"; chosen = await tryTiers(buildIllustrationCompositeTiers(publicId, idea)); }
      else uploadDiag = "réponse upload sans public_id";
    } catch (e) { uploadDiag = extractHttpError(e); }
  } else if (!presetConfigured) {
    uploadDiag = "preset non configuré (illustrations IA désactivées)";
  }

  // ÉTAPE 2 -- GABARIT AUTO : canevas sombre + lueurs orange/teal + logo + titre, synthétisé depuis
  // le logo. Instantané, fiable, aucun réseau lourd -> c'est le rendu par défaut sans upload preset.
  if (!chosen) chosen = await tryTiers(buildBrandCanvasTiers(idea.hook, badge));

  // ÉTAPE 3 -- ultimes filets : FETCH (si le compte l'autorise) puis image Pollinations BRUTE. Ces
  // deux crans ont besoin de l'illustration pré-chauffée.
  if (!chosen) {
    if (!illoWarm) {
      try { await this.helpers.httpRequest({ method: "GET", url: illoUrl, timeout: 75000, json: false }); illoWarm = true; }
      catch (e) { lastError = `pollinations → ${extractHttpError(e)}`; }
    }
    if (illoWarm) {
      chosen = await tryTiers(buildFetchTiers(illoUrl, idea.hook));
      if (!chosen) chosen = { label: "image brute", url: illoUrl, raw: true };
    }
  }

  if (!chosen) {
    staticData.sessions[sender] = { stage: "idle", platform: null, current_idea: null, refine_notes: [] };
    result.text = `⚠️ Le générateur d'image (Pollinations) n'a pas répondu à temps. Réessaie dans un instant.\n\n_(diag: ${lastError})_`;
    return [{ json: result }];
  }

  staticData.sessions[sender] = { stage: "idle", platform: null, current_idea: null, refine_notes: [] };
  result.image_url = chosen.url;
  const diagTail = uploadDiag ? `upload=${uploadDiag} ; ${lastError}` : lastError;
  // LÉGENDE PRÊTE À PUBLIER envoyée AVEC l'image : caption on-brand + hashtags populaires, pour que
  // l'équipe n'ait qu'à copier-coller lors de la publication (demande utilisateur).
  const caption = String(idea.caption || idea.hook || "");
  const tags = (idea.hashtags && idea.hashtags.length) ? idea.hashtags.join(" ") : "";
  const post = `${caption}${tags ? "\n\n" + tags : ""}`;
  // Rendu "complet" = illustration composée (tous crans), gabarit auto, ou gabarit fourni + texte.
  const isFull = ["illustration", "gabarit auto", "+ texte"].some(s => chosen.label && chosen.label.indexOf(s) !== -1);
  if (chosen.raw) {
    result.text = `✅ *Visuel prêt* (montage simplifié) :\n\n${post}\n\n_(diag: ${diagTail || "montage désactivé"})_`;
  } else if (!isFull) {
    result.text = `✅ *Visuel prêt* (montage partiel : ${chosen.label}) :\n\n${post}`;
  } else {
    result.text = `✅ *Prêt à publier !*\n\n${post}`;
  }
}

return [{ json: result }];
